# name: longest_run_shorter_choice_rate
# description: Among pairs whose sequences have the same number of switches but different longest-run lengths, the rate at which the sequence with the SHORTER longest run is chosen; observed above null means people penalise long streaks more than the model's span/switch terms imply.
def test_statistic(df):
    import itertools
    seqs = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    lr = {s: max(len(list(g)) for _, g in itertools.groupby(s)) for s in seqs}
    sw = {s: sum(x != y for x, y in zip(s, s[1:])) for s in seqs}
    la = df["sequence_a"].map(lr).to_numpy(); lb = df["sequence_b"].map(lr).to_numpy()
    sa = df["sequence_a"].map(sw).to_numpy(); sb = df["sequence_b"].map(sw).to_numpy()
    m = (sa == sb) & (la != lb)
    if m.sum() == 0:
        return 0.5
    c = df["chose_left"].to_numpy()[m]
    shorter_left = (la < lb)[m]
    return float(np.mean(np.where(shorter_left, c, 1 - c)))

# name: switch_preference_length_slope
# description: Slope (per flip of length) of the rate of choosing the more-switching sequence among pairs with unequal switch rates; observed above null means the preference for switching grows with length faster than the model predicts (below null: slower or reverses).
def test_statistic(df):
    seqs = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    sw = {s: sum(x != y for x, y in zip(s, s[1:])) / (len(s) - 1) for s in seqs}
    ra = df["sequence_a"].map(sw).to_numpy(); rb = df["sequence_b"].map(sw).to_numpy()
    L = df["sequence_a"].str.len().to_numpy().astype(float)
    m = ra != rb
    y = np.where(ra > rb, df["chose_left"].to_numpy(), 1 - df["chose_left"].to_numpy())[m].astype(float)
    x = L[m]
    if x.size < 3 or np.var(x) == 0:
        return 0.0
    return float(np.cov(x, y, bias=True)[0, 1] / np.var(x))

# name: long_streak_count_choice_rate
# description: Among pairs whose sequences differ in the number of runs of 3+ identical flips but have equal switch counts and equal longest run, the rate the sequence with FEWER such streaks is chosen; observed above null means people penalise each extra visible streak beyond what span/switch terms capture.
def test_statistic(df):
    import itertools
    seqs = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    runs = {s: [len(list(g)) for _, g in itertools.groupby(s)] for s in seqs}
    ns = {s: sum(r >= 3 for r in v) for s, v in runs.items()}
    lr = {s: max(v) for s, v in runs.items()}
    na = df["sequence_a"].map(ns).to_numpy(); nb = df["sequence_b"].map(ns).to_numpy()
    sa = df["sequence_a"].map(lambda s: len(runs[s])).to_numpy(); sb = df["sequence_b"].map(lambda s: len(runs[s])).to_numpy()
    m = (na != nb) & (sa == sb)
    if m.sum() == 0:
        # fall back: pairs differing in streak count at all
        m = na != nb
    if m.sum() == 0:
        return 0.5
    c = df["chose_left"].to_numpy()[m]
    return float(np.mean(np.where((na < nb)[m], c, 1 - c)))

# name: switch_preference_participant_variance
# description: Variance across participants of each person's rate of choosing the sequence with more switches (pairs with unequal switch counts); observed above null means individuals differ in switching preference more than the model's person-level weights allow (below null: less).
def test_statistic(df):
    seqs = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    sw = {s: sum(x != y for x, y in zip(s, s[1:])) for s in seqs}
    sa = df["sequence_a"].map(sw).to_numpy(); sb = df["sequence_b"].map(sw).to_numpy()
    m = sa != sb
    y = np.where(sa > sb, df["chose_left"].to_numpy(), 1 - df["chose_left"].to_numpy())
    g = pd.DataFrame({"p": df["participant_id"].to_numpy()[m], "y": y[m]})
    return float(g.groupby("p")["y"].mean().var())

# name: symmetric_sequence_choice_rate
# description: Among pairs where exactly one sequence is mirror-symmetric (a palindrome or equal to its reversed H/T complement), the rate the symmetric one is chosen; observed below null means people see symmetry as designed/non-random, which the model does not penalise.
def test_statistic(df):
    seqs = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    tr = str.maketrans("HT", "TH")
    sym = {s: float(s == s[::-1] or s == s[::-1].translate(tr)) for s in seqs}
    sa = df["sequence_a"].map(sym).to_numpy(); sb = df["sequence_b"].map(sym).to_numpy()
    m = sa != sb
    if m.sum() == 0:
        return 0.5
    c = df["chose_left"].to_numpy()[m]
    return float(np.mean(np.where((sa > sb)[m], c, 1 - c)))
